import { execFileSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterEach, describe, expect, it } from 'vitest';

const SCRIPT_PATH = fileURLToPath(new URL('../scripts/vendor-shared.mjs', import.meta.url));
const SHARED_UTILITIES_DIR = fileURLToPath(new URL('../../shared/src/utilities', import.meta.url));

const BANNER =
  '// GENERATED by packages/cli/scripts/vendor-shared.mjs from packages/shared — do not edit.\n';

const tempDirs: string[] = [];

function makeTempDir(): string {
  const dir = mkdtempSync(join(tmpdir(), 'goals-cli-vendor-'));
  tempDirs.push(dir);
  return dir;
}

function write(root: string, relativePath: string, contents: string): void {
  const file = join(root, relativePath);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, contents);
}

function runVendor(srcDir: string, destDir: string): void {
  execFileSync(process.execPath, [SCRIPT_PATH, srcDir, destDir], { stdio: 'pipe' });
}

/** Removes the banner and the `.js` suffixes so a vendored file can be compared to its source. */
function unwrap(source: string): string {
  const body = source.startsWith(BANNER) ? source.slice(BANNER.length) : source;
  return body.replace(/(\bfrom\s+|\bimport\s+)(['"])(\.{1,2}\/[^'"]+)\.js\2/g, '$1$2$3$2');
}

function listVendoredFiles(dir: string, prefix = ''): string[] {
  const files: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const relative = prefix === '' ? entry.name : `${prefix}/${entry.name}`;
    if (entry.isDirectory()) files.push(...listVendoredFiles(join(dir, entry.name), relative));
    else files.push(relative);
  }
  return files.sort();
}

afterEach(() => {
  for (const dir of tempDirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

describe('vendor-shared', () => {
  it('rewrites relative specifiers and keeps already-suffixed and bare specifiers intact', () => {
    const root = makeTempDir();
    const srcDir = join(root, 'utilities');
    const destDir = join(root, 'vendor');
    write(join(srcDir, 'quarterly-markdown'), 'b.ts', 'export const b = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), 'c.ts', 'export const c = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), 'side.ts', 'export const side = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), 'done.ts', 'export const done = 1;\n');
    write(join(srcDir, 'cli-contract'), 't.ts', 'export type T = string;\n');
    write(
      join(srcDir, 'quarterly-markdown'),
      'a.ts',
      "import { b } from './b';\nexport { c } from './c';\nimport type { T } from '../cli-contract/t';\nimport './side';\nimport { ok } from './done.js';\nimport pkg from 'node:path';\n"
    );

    runVendor(srcDir, destDir);

    const output = readFileSync(join(destDir, 'quarterly-markdown', 'a.ts'), 'utf8');
    const [bannerLine, ...rest] = output.split('\n');
    expect(bannerLine).toBe(BANNER.trimEnd());
    expect(rest.join('\n')).toBe(
      "import { b } from './b.js';\nexport { c } from './c.js';\nimport type { T } from '../cli-contract/t.js';\nimport './side.js';\nimport { ok } from './done.js';\nimport pkg from 'node:path';\n"
    );
  });

  it('skips test files and fixture directories', () => {
    const root = makeTempDir();
    const srcDir = join(root, 'utilities');
    const destDir = join(root, 'vendor');
    write(join(srcDir, 'quarterly-markdown'), 'kept.ts', 'export const kept = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), 'dropped.test.ts', 'export const dropped = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), '__fixtures__/case.ts', 'export const c = 1;\n');
    write(join(srcDir, 'quarterly-markdown'), '__fixtures__/case.json', '{}\n');
    write(join(srcDir, 'cli-contract'), 'index.ts', 'export type X = number;\n');

    runVendor(srcDir, destDir);

    expect(listVendoredFiles(join(destDir, 'quarterly-markdown'))).toEqual(['kept.ts']);
    expect(existsSync(join(destDir, 'quarterly-markdown', '__fixtures__'))).toBe(false);
    expect(listVendoredFiles(join(destDir, 'cli-contract'))).toEqual(['index.ts']);
  });

  it('wipes the destination before copying', () => {
    const root = makeTempDir();
    const srcDir = join(root, 'utilities');
    const destDir = join(root, 'vendor');
    write(join(srcDir, 'quarterly-markdown'), 'a.ts', 'export const a = 1;\n');
    write(join(srcDir, 'cli-contract'), 'index.ts', 'export type X = number;\n');
    write(destDir, 'old.ts', 'export const old = 1;\n');

    runVendor(srcDir, destDir);

    expect(existsSync(join(destDir, 'old.ts'))).toBe(false);
    expect(existsSync(join(destDir, 'quarterly-markdown', 'a.ts'))).toBe(true);
  });

  it('rejects a relative import that does not resolve to a .ts file', () => {
    const root = makeTempDir();
    const srcDir = join(root, 'utilities');
    const destDir = join(root, 'vendor');
    write(join(srcDir, 'quarterly-markdown'), 'sub/nested.ts', 'export const nested = 1;\n');
    write(
      join(srcDir, 'quarterly-markdown'),
      'bad.ts',
      "import { nested } from './sub';\nexport const bad = nested;\n"
    );
    write(join(srcDir, 'cli-contract'), 'index.ts', 'export type X = number;\n');

    expect(() => runVendor(srcDir, destDir)).toThrow(/which is not a \.ts file/);
  });

  it('vendors the real shared sources byte-for-byte apart from the .js rewrite', () => {
    const destDir = join(makeTempDir(), 'vendor');

    runVendor(SHARED_UTILITIES_DIR, destDir);

    expect(listVendoredFiles(destDir)).toEqual([
      'cli-contract/index.ts',
      'quarterly-markdown/dateFormat.ts',
      'quarterly-markdown/generate.ts',
      'quarterly-markdown/htmlToPlainText.ts',
      'quarterly-markdown/index.ts',
      'quarterly-markdown/types.ts',
      'quarterly-markdown/year.ts',
    ]);

    for (const file of listVendoredFiles(destDir)) {
      const [group] = file.split('/');
      const original = readFileSync(
        join(SHARED_UTILITIES_DIR, group, file.slice(group.length + 1)),
        'utf8'
      );
      const output = readFileSync(join(destDir, file), 'utf8');

      expect(output.startsWith(BANNER)).toBe(true);
      expect(unwrap(output)).toBe(original);

      for (const match of output.matchAll(/(?:\bfrom\s+|\bimport\s+)(['"])(\.{1,2}\/[^'"]+)\1/g)) {
        const specifier = match[2].replace(/\.js$/, '');
        const sibling = join(dirname(join(destDir, file)), `${specifier}.ts`);
        expect(existsSync(sibling)).toBe(true);
      }
    }
  });
});
